select 'b3e91f6c47d2', m.mx + row_number() over (order by t.i), t.e->>'lib', t.e->'chunk'
  from jsonb_array_elements($kb$[{"lib": "field", "chunk": {"id": "mutcd-6a-status-1", "state": "US", "tier": "core", "title": "MUTCD: what it is and which edition is current", "topic": "Traffic control: MUTCD basics and status", "text": "The MUTCD (Manual on Uniform Traffic Control Devices) is the national standard for signs, cones, flaggers and every other traffic control device on roads open to the public. Part 6 covers temporary traffic control: construction, utility work, maintenance and incidents. The current edition is the 11th Edition, dated December 2023 and effective January 18, 2024. FHWA issued Revision 1 (dated December 2025) by a final rule effective March 5, 2026; it makes technical and editorial corrections, and the key Part 6 tables (sign spacing, tapers, stopping sight distance) read the same in Revision 1. States had two years, to January 18, 2026, to adopt the 11th Edition, either as is, with a state supplement, or as their own state manual that substantially conforms. The 11th Edition renumbered Part 6: flaggers are now Chapter 6D, tapers are Section 6B.08, and the typical applications are Chapter 6P (TA-1 to TA-54). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition Part 6; FHWA final rule 91 FR (Mar. 5, 2026), FR Doc. 2026-04365; 23 CFR 655.601(d)(2)(i), 655.603(b)(3)", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6a-status-2", "state": "US", "tier": "core", "title": "MUTCD: how a state adopts it and whose manual wins", "topic": "Traffic control: MUTCD basics and status", "text": "Federal rule 23 CFR 655.603 makes the MUTCD the national standard for all traffic control devices on streets and highways open to public travel. A state may use the national manual as is, add a state supplement, or publish its own state MUTCD, but the state document has to be in substantial conformance: at a minimum it keeps the national Standard statements. States must adopt FHWA changes within two years of the final rule's effective date. That is why the 11th Edition (effective January 18, 2024) had a January 18, 2026 state deadline, and Revision 1 (effective March 5, 2026) gives states until March 5, 2028 by the same two-year rule. On the job, the order is: the approved traffic control plan or permit for that road, then the state's manual or supplement and DOT standard plans, then the national MUTCD. A city or county can be stricter than the state. If you do not know which edition your state is on, ask the agency that issued the permit.", "source": "23 CFR 655.603(a), (b)(1)-(3); FHWA final rule FR Doc. 2026-04365 (effective Mar. 5, 2026); MUTCD state information page", "url": "https://www.law.cornell.edu/cfr/text/23/655.603", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6a-words-1", "state": "US", "tier": "core", "title": "MUTCD: what Standard, Guidance, Option and Support mean", "topic": "Traffic control: MUTCD basics and status", "text": "Every paragraph in the MUTCD is labeled. Standard means required: it uses the word shall, and you do not deviate without an engineering study where the manual allows one. Guidance means recommended practice: it uses should, and you follow it unless engineering judgment says otherwise. Option means allowed: it uses may. Support is background only. This matters when a crew asks if something is the law. Examples from Part 6: high-visibility apparel for workers in the right-of-way is a Standard (Section 6C.05); lighting flagger stations at night is a Standard (Section 6D.06); taper lengths (Section 6B.08) and cone spacing (Section 6K.01) are Guidance; using Table 6B-2 distances for a buffer space is an Option. The typical application drawings in Chapter 6P are generally treated as Guidance, except the notes that are labeled Standard. A state manual can turn national Guidance into a state Standard. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6P.01 para. 2, 6C.05, 6D.06, 6B.08, 6K.01, 6B.06", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "medium", "kind": "summary", "license": "gov-us", "note": "Definitions of the four labels are in MUTCD Part 1, not re-read on 2026-11-20; the Part 6 examples were read."}},
{"lib": "field", "chunk": {"id": "mutcd-6b-plan-1", "state": "US", "tier": "core", "title": "Traffic control plan (TCP): when you need one and what it covers", "topic": "Traffic control: MUTCD basics and status", "text": "A temporary traffic control (TTC) plan describes the signs, devices and flagging used to move drivers, bikes and pedestrians through or around the work. The MUTCD says a plan should be developed for any planned work that affects road users, and planning should be finished before the site is occupied, even on minor jobs (Section 6B.01). The plan can be a detailed drawing or simply a reference to a typical application or the agency's standard plan. It should be prepared by someone knowledgeable (trained or certified) in traffic control, should keep an accessible route for pedestrians, and any change or alternate plan should be approved before it is used. The public agency with jurisdiction over the road is responsible for traffic control plans and devices (Section 6A.01), which is why the city, county or state permit decides what is approved. Speed limit reductions should be avoided where practical and kept to 10 mph or less; larger drops need a restrictive feature, extra notice and a step-down (Section 6B.01). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6A.01 para. 11, 6B.01 paras. 2-3, 5-11, 14, 17-20", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6b-zone-1", "state": "US", "tier": "core", "title": "Work zone parts: advance warning, transition, activity and termination areas", "topic": "Traffic control: parts of a work zone", "text": "A temporary traffic control zone has four parts (Section 6B.03). 1, Advance warning area: where drivers are told what is coming. It can be one sign or a vehicle with flashing lights, or a series of signs (Section 6B.04). 2, Transition area: where drivers are moved out of their normal path, usually with a taper of cones or drums. Except for mobile work, the redirect has to be made with channelizing devices or other traffic control devices (Section 6B.05, Standard). 3, Activity area: where the work happens. It holds the work space (closed to traffic, for workers, equipment and material), the traffic space (where traffic runs past) and the buffer space (empty separation) (Section 6B.06). 4, Termination area: where drivers return to their normal path, from the end of the work to the last device. An END ROAD WORK sign or a downstream taper may be used (Section 6B.07). The work zone runs from the first warning sign or flashing vehicle light to the END ROAD WORK sign or the last device (Section 6B.02). Set up in that order going with traffic and take down in reverse. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6B.02 to 6B.07", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6b-activity-1", "state": "US", "tier": "core", "title": "Buffer space: what it is, how long, and what cannot be in it", "topic": "Traffic control: tapers and buffer spaces", "text": "The buffer space is empty road between traffic and the work space. It gives a driver who misses the taper room to stop before reaching the crew. A longitudinal buffer sits ahead of the work space; a lateral buffer sits beside it, next to an open trench, a drop-off or opposing traffic. The MUTCD says no work, and no storage of equipment, vehicles or material, should be in a buffer space (Section 6B.06, Guidance). If a truck with an attenuator, an arrow board or a message sign sits in the closed lane, only the part upstream of it counts as buffer. The width of a lateral buffer is set by engineering judgment. For the length of a longitudinal buffer the manual lets you use the stopping sight distances in Table 6B-2: 20 mph 115 ft, 25 mph 155 ft, 30 mph 200 ft, 35 mph 250 ft, 40 mph 305 ft, 45 mph 360 ft, 50 mph 425 ft, 55 mph 495 ft, 60 mph 570 ft, 65 mph 645 ft, 70 mph 730 ft, 75 mph 820 ft. Use the posted speed, the off-peak 85th-percentile speed before work started, or the expected operating speed. The same table may be used to place a flagger station. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6B.06 paras. 6-15; Table 6B-2; Section 6D.06 para. 3", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6b-signspacing-1", "state": "US", "tier": "core", "title": "Advance warning sign spacing (Table 6B-1: distances A, B and C)", "topic": "Traffic control: advance warning signs", "text": "Table 6B-1 gives the recommended minimum spacing for a three-sign series. A is from the taper or point of restriction back to the first sign, B is from the first sign to the second, C is from the second to the third. Urban low speed: 100 ft, 100 ft, 100 ft. Urban high speed: 350, 350, 350 ft. Rural: 500, 500, 500 ft. Expressway or freeway: 1,000 ft, 1,500 ft and 2,640 ft. The national table does not put mph numbers on low speed and high speed; the footnote says the road agency decides the speed category, and several state manuals do it by speed. Section 6B.04 adds rules of thumb: on urban streets the sign nearest the work should be about 4 to 8 times the speed limit in feet (use the high end for higher speeds); on rural highways the first sign should be 8 to 12 times the speed limit in feet, and a multi-sign series should cover 1,500 ft or more; on freeways signing may reach half a mile or more; a single sign on a low-speed residential street may be as close as 100 ft. Lengthen them for hills, curves and queues, and sign any side street that enters inside the series. ROAD WORK AHEAD should be the first sign a driver sees. The approved plan governs.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Table 6B-1 and footnotes; Section 6B.04 paras. 3-8; Sections 6H.02, 6H.03", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6b-taper-1", "state": "US", "tier": "core", "title": "Taper length formulas: L = WS squared / 60 and L = WS", "topic": "Traffic control: tapers and buffer spaces", "text": "Taper length L in feet comes from Table 6B-4. For 40 mph or less: L = W x S x S / 60. For 45 mph or more: L = W x S. W is the width of the offset in feet (how far traffic is moved sideways, usually the lane width). S is the posted speed limit, or the off-peak 85th-percentile speed before work starts, or the expected operating speed, in mph. Table 6B-3 then sets the length by type of taper. Merging taper (closing a lane where traffic has to merge): at least L. Shifting taper (moving traffic sideways with no merge): at least 1/2 L. Shoulder taper (closing a shoulder): at least 1/3 L. One-lane, two-way traffic taper (the short taper in front of a flagger): 50 ft minimum, 100 ft maximum. Downstream taper (end of the work space): 50 ft minimum, 100 ft maximum. In the one-lane two-way taper and the downstream taper the devices go about 20 ft apart. A 12 ft lane at 35 mph: 12 x 35 x 35 / 60 = 245 ft. A 12 ft lane at 55 mph: 12 x 55 = 660 ft. Longer is not always better: in town, short blocks and driveways can make a long taper worse (Section 6B.08). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6B.08 paras. 3-14; Tables 6B-3 and 6B-4", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6b-taper-2", "state": "US", "tier": "core", "title": "Taper lengths worked out by speed for 10, 11 and 12 ft lanes", "topic": "Traffic control: tapers and buffer spaces", "text": "Merging taper lengths from the MUTCD formulas in Table 6B-4 (L = W x S x S / 60 at 40 mph or less, L = W x S at 45 mph or more), worked out here, in feet. 12 ft lane: 20 mph 80, 25 mph 125, 30 mph 180, 35 mph 245, 40 mph 320, 45 mph 540, 50 mph 600, 55 mph 660, 60 mph 720, 65 mph 780, 70 mph 840. 11 ft lane: 25 mph 115, 30 mph 165, 35 mph 225, 40 mph 293, 45 mph 495, 55 mph 605, 65 mph 715. 10 ft lane: 25 mph 104, 30 mph 150, 35 mph 204, 40 mph 267, 45 mph 450, 55 mph 550, 65 mph 650. A shifting taper is half of these. A shoulder taper is one third, using the shoulder width as W: an 8 ft shoulder at 45 mph is 8 x 45 / 3 = 120 ft, and at 55 mph 147 ft. Notice the jump between 40 and 45 mph, where the formula changes: a 12 ft lane goes from 320 ft to 540 ft. These are minimums from the national formula; round up, and use your state's table if it has one. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Tables 6B-3 and 6B-4 (lengths computed from the formulas, not printed in the MUTCD)", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Computed values; the 12 ft column matches California MUTCD 2026 Table 6B-3(CA)."}},
{"lib": "field", "chunk": {"id": "mutcd-6b-setup-1", "state": "US", "tier": "core", "title": "Worked example: closing one lane for a utility job on a 35 mph street", "topic": "Traffic control: tapers and buffer spaces", "text": "Example using the national MUTCD numbers for a 12 ft lane closed on a multi-lane 35 mph city street. Merging taper: L = 12 x 35 x 35 / 60 = 245 ft (Tables 6B-3 and 6B-4). Cones in the taper no more than 35 ft apart, which is 8 cones for 245 ft; cones along the work space no more than 70 ft apart (Section 6K.01). Buffer space ahead of the work, if used: 250 ft at 35 mph (Table 6B-2), kept empty. Downstream taper: 50 to 100 ft with cones about 20 ft apart (Section 6B.08). Advance signs: three signs. If the agency treats the street as urban low speed they are at least 100 ft apart; as urban high speed, 350 ft apart (Table 6B-1). ROAD WORK AHEAD or UTILITY WORK AHEAD comes first, then the lane closed sign, then the lane ends sign. At night the cones must be at least 28 inches tall with reflective bands (Section 6K.03). Same job at 45 mph: taper 540 ft, cones 45 ft apart in the taper and 90 ft along the work, buffer 360 ft. This is arithmetic from the national manual, not an approved plan. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Tables 6B-1, 6B-2, 6B-3, 6B-4; Sections 6B.08, 6K.01, 6K.03, 6H.24", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6c-ped-1", "state": "US", "tier": "core", "title": "Sidewalk closed: what you owe pedestrians", "topic": "Traffic control: pedestrians and sidewalks", "text": "If the work zone affects where people walk, adequate pedestrian access and walkways shall be provided (Section 6C.02, Standard). Tell people before they reach the closure, and send them across at an intersection, not mid-block, so nobody walks up to a dead end. A good temporary route does three things: no conflict with the work or equipment, no conflict with traffic moving around the site, and a convenient, accessible path that is close to what the sidewalk was. Do not take the pedestrian route away just to park trucks or store material. Tape, rope and plastic chain should not be used to control pedestrians because a person using a cane cannot detect them. Keep truck and equipment crossings of the walkway to a minimum and use a flagger when they cross. Where the walkway is close to traffic, separate it with temporary traffic barrier; normal curb does not count as a barrier. Signs: SIDEWALK CLOSED (R9-9) at the closure, SIDEWALK CLOSED USE OTHER SIDE (R9-10), and SIDEWALK CLOSED AHEAD CROSS HERE (R9-11) at the crossing before it. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6C.02 paras. 2-9, 14-17, 20, 23, 28; Section 6G.10", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6c-ada-1", "state": "US", "tier": "core", "title": "Temporary pedestrian route: ADA numbers (width, ramps, edging)", "topic": "Traffic control: pedestrians and sidewalks", "text": "When a sidewalk or crosswalk is closed or moved, the temporary route shall be detectable and have accessibility features consistent with the route it replaces, and a barrier that a long cane can detect shall span the full width of the closed sidewalk (Section 6C.03, Standard). Numbers from Part 6: keep the existing width where practical; 60 inches is the target, and where that cannot be held provide a 60 by 60 inch passing space at least every 200 ft (Section 6C.02). The sidewalk detour drawing (TA-28) allows a 48 inch route with a 60 inch passing area every 200 ft. Temporary ramps: slope 12:1 (8.33 percent) or flatter, slip-resistant, with a landing at least 48 by 48 inches and cross-slope 2 percent or flatter (TA-28, Standard). Surface: smooth, hard, no abrupt grade changes. Detectable edging along a channelized route: top at least 8 inches above the walk, bottom no more than 2 inches above it, continuous (Section 6M.04). Pedestrian channelizing devices: hand-trailing edge 32 to 38 inches high (Section 6K.02). Printed signs do not help a blind pedestrian; a continuous detectable barrier does. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6C.02 para. 11, 6C.03 paras. 4-6, 6K.02 para. 8, 6M.04 para. 2; Figure 6P-28 (TA-28) notes 1, 2, 14", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6c-worker-1", "state": "US", "tier": "core", "title": "Worker safety in a work zone: what the MUTCD says to plan for", "topic": "Traffic control: parts of a work zone", "text": "Section 6C.04 lists the things that should be considered to protect workers. Training: all workers should be trained to work next to traffic in a way that lowers their exposure, and workers with traffic control duties trained in the devices. Temporary traffic barrier along the work space, depending on how close traffic is, its speed, how long the job lasts, the time of day and the volume. Speed reduction: speed zoning, funneling, lane reduction, law enforcement or flaggers. Activity area planned so backing of trucks and equipment is kept to a minimum. Worker safety planning: a trained person does a basic hazard assessment of the site and the job classifications (the manual points to the OSHA General Duty Clause and 29 CFR 1926.20(b)(2)). Extras that may be used: a shadow vehicle with a truck-mounted attenuator, closing the road and detouring traffic, police presence on short risky jobs, lighting for night work, and special devices such as rumble strips, message signs, warning lights or intrusion alarms. The section warns that overusing special devices makes drivers stop noticing them. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6C.04 paras. 1-5", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6c-hivis-1", "state": "US", "tier": "core", "title": "High-visibility vest: what class the MUTCD requires", "topic": "Traffic control: flaggers", "text": "All workers within the right-of-way who are inside the work zone, flaggers and emergency responders included, shall wear high-visibility safety apparel that meets Performance Class 2 or 3 of ANSI/ISEA 107-2015 (Section 6C.05, Standard). A person the employer designates picks Class 2 or Class 3 for the job. Background material is fluorescent orange-red or fluorescent yellow-green, or both; the retroreflective material is orange, yellow, white, silver or yellow-green. Flaggers working at night should wear Class 3 (Guidance). Police directing traffic or working a closure wear it too; emergency and law enforcement personnel may wear an ANSI/ISEA 207-2006 public safety vest instead. OSHA has the same floor for trench crews: workers exposed to public vehicle traffic must wear warning vests or other reflective or high-visibility garments (29 CFR 1926.651(d)), and flagger garments must follow MUTCD Part 6 (29 CFR 1926.201(a)). Some states are stricter, for example on colors or on Class 3 for flaggers at all times. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6C.05 paras. 1-7; 29 CFR 1926.651(d); 29 CFR 1926.201(a)", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6d-flagger-qual-1", "state": "US", "tier": "core", "title": "Flagger training: what the national MUTCD says", "topic": "Traffic control: flaggers", "text": "The national MUTCD does not issue flagger cards. Section 6D.01 is Guidance: because flaggers are responsible for public safety and deal with the public more than any other worker, they should be trained in safe traffic control practices and public contact techniques. A flagger should be able to: receive and pass on specific instructions clearly, firmly and courteously; move fast enough to get out of the way of an errant vehicle; control the paddle or flag so drivers get clear guidance as conditions change; apply safe practices under stress or in an emergency; and recognize a dangerous traffic situation and warn the crew in time. The card or certification rule comes from the state: the state DOT specifications, the state MUTCD or supplement, or the state safety agency. Many states name the courses they accept and how long a card lasts (2, 3 or 4 years are common). OSHA ties in through 29 CFR 1926.201(a): flagger signaling and the use of flaggers must conform to Part 6 of the MUTCD. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6D.01 para. 1 (Guidance); 29 CFR 1926.201(a)", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6d-flagger-paddle-1", "state": "US", "tier": "core", "title": "Flagger equipment: STOP/SLOW paddle, flag and flashlight", "topic": "Traffic control: flaggers", "text": "The STOP/SLOW paddle should be the primary and preferred hand-signaling device because it gives drivers clearer guidance than a red flag (Section 6D.02, Guidance). The paddle shall be an octagon on a rigid handle and shall be retroreflectorized when used at night (Standard). The STOP face is red with white letters and border; the SLOW face is orange with black letters and border. Lights may be added to the paddle; if they flash, the rate is 50 to 60 flashes a minute, with white or red lights on the STOP face and white or yellow on the SLOW face. Flags should be limited to emergencies (Section 6D.03). A flag shall be red or fluorescent orange-red, at least 24 inches square, fastened to a staff about 36 inches long, and retroreflectorized at night. In an emergency at night at a station that is not lit, a flashlight with a red glow cone may be added: flashlight in the left hand, paddle or flag in the right (Section 6D.04). The minimum paddle size is set in the figure and in state manuals; check your state's size. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6D.02 paras. 1-9, 6D.03 paras. 1-4, 6D.04 paras. 1-2", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "National minimum paddle width (18 in in earlier editions) was not confirmed from the 11th Edition text on 2026-11-20; left out on purpose."}},
{"lib": "field", "chunk": {"id": "mutcd-6d-flagger-signals-1", "state": "US", "tier": "core", "title": "Flagger signals: stop, proceed, slow", "topic": "Traffic control: flaggers", "text": "With the paddle (Section 6D.05, Standard). To stop traffic: face the drivers, hold the STOP face toward them with the arm straight out from the body, and raise the free hand with the palm toward traffic, above shoulder level. To let traffic go: turn the SLOW face toward the stopped drivers and wave them on with the free hand. To alert or slow traffic: hold the SLOW face toward traffic with the arm straight out; you may also move the free hand up and down, palm down. With a flag (emergencies): to stop, hold the staff straight out across the lane so the whole flag hangs below it, free palm raised; to let traffic go, lower the flag and arm out of sight and wave with the free hand, and never wave traffic on with the flag. Hand signals alone, with no paddle, flag or automated flagger device, shall not be used on a one-lane two-way operation. Where to stand: on the shoulder next to the lane you control, or in the closed lane, before traffic stops. Step into the lane only after the vehicles have stopped. Stay visible and stand alone. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6D.05 paras. 2-6; Figure 6D-1", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6d-flagger-station-1", "state": "US", "tier": "core", "title": "Flagger station: where to put it and night lighting", "topic": "Traffic control: flaggers", "text": "A flagger station shall be placed so approaching drivers have enough distance to stop at the stopping point (Section 6D.06, Standard). The stopping sight distances in Table 6B-2 may be used: 25 mph 155 ft, 30 mph 200 ft, 35 mph 250 ft, 40 mph 305 ft, 45 mph 360 ft, 50 mph 425 ft, 55 mph 495 ft, 60 mph 570 ft, 65 mph 645 ft. Increase the distance on a downgrade. The station should be far enough ahead of the crew that a car that runs the stop can still stop before the work space, and the flagger should pick an escape route before starting. Except in an emergency, a flagger station shall have advance warning signs ahead of it, and shall be illuminated when flagging at night (Standard). A Flagger sign (W20-7 symbol or W20-7a word sign) should be used ahead of any flagger; a BE PREPARED TO STOP sign may be added and goes between the Flagger sign and the ONE LANE ROAD sign. On a curve or hill crest, lengthen the buffer so the flagger and the back of the line of stopped cars can be seen in time (TA-10). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6D.06 paras. 1-5; Table 6B-2; Section 6H.15; Figure 6P-10 (TA-10) notes 6-8", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6e-onelane-1", "state": "US", "tier": "core", "title": "One lane, two-way traffic: flaggers, pilot car, signal or stop signs", "topic": "Traffic control: flaggers", "text": "When both directions have to share one lane for a short distance, movements from each end shall be coordinated (Section 6E.01, Standard). The ways to do it: flaggers, a flag transfer, a pilot car, a temporary traffic signal, or STOP or YIELD signs. Flagger method: a flagger at each end, one of them named the lead, talking by radio or by hand signals that cannot be mistaken for flagging signals. One flagger is allowed only if that flagger can see the whole zone, on a short, low-volume, straight job; the single flagger should stand on the shoulder opposite the work or where visibility is good (Section 6E.02). Flag transfer: the last driver in carries a red flag or token to the other flagger; only for short sections, usually no more than 1 mile (Section 6E.03). Pilot car: a PILOT CAR FOLLOW ME sign (G20-4) shall be on the vehicle and the operation shall be coordinated with the control at each end (Section 6E.04). STOP or YIELD control: only on low-volume roads where drivers can see the other end and oncoming traffic (Section 6E.06). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6E.01 to 6E.06", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6f-signs-1", "state": "US", "tier": "core", "title": "Work zone signs: mounting height, color and portable stands", "topic": "Traffic control: advance warning signs", "text": "Work zone warning signs are orange with black legend. Signs used at night shall be retroreflective or illuminated, and street lighting does not count as illumination (Section 6F.01, Standard). Put signs on the right side of the road unless the manual says otherwise. Height to the bottom of the sign: at least 5 ft at the side of a rural road; at least 7 ft in business, commercial or residential areas where parked cars or people would block the view, and at least 7 ft above a sidewalk. A sign on a barricade or portable stand shall be at least 1 ft above the traveled way. Signs on portable supports that do not reach the 5 or 7 ft heights should not be used for more than 3 days (Section 6F.02). Take signs down or cover them as soon as they no longer apply, including during a short stop in the work (Section 6A.03, Standard). Standard size for the diamond warning signs such as ROAD WORK AHEAD and the Flagger sign is 36 by 36 inches on conventional roads and 48 by 48 inches on freeways and expressways; the 30 by 30 inch minimum is only for low-volume rural roads, local streets and roads at 30 mph or less (Section 6F.01, Table 6H-1). The approved plan governs.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6F.01 paras. 2-12, 6F.02 paras. 1-11, 6A.03 para. 4; Table 6H-1", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6h-signs-1", "state": "US", "tier": "core", "title": "Which warning signs a utility crew uses, with sign numbers", "topic": "Traffic control: advance warning signs", "text": "Common Part 6 signs. ROAD WORK AHEAD (W20-1): the general warning and the first sign drivers should see; STREET may replace ROAD. UTILITY WORK AHEAD (W21-7): may be used instead of ROAD WORK for utility operations on or next to the road (Section 6H.24). Flagger symbol (W20-7) or FLAGGER word sign (W20-7a): ahead of any flagger. ONE LANE ROAD AHEAD (W20-4): for a one-lane two-way operation. BE PREPARED TO STOP (W3-4): optional, between the Flagger sign and ONE LANE ROAD. Lane closed signs (W20-5) and lane ends signs (W4-2): for a lane closure on a multi-lane road. SHOULDER WORK (W21-5) and RIGHT or LEFT SHOULDER CLOSED (W21-5a): shoulder work with the road open. Workers symbol (W21-1): workers in or near the road. STEEL PLATE AHEAD (W8-24): warns that temporary plates may be uneven and slippery when wet (Section 6H.28). END ROAD WORK (G20-2): near the downstream end; it may go on the back of a sign facing the other way. SIDEWALK CLOSED signs are R9-9, R9-10 and R9-11. Add a warning sign on any side street or busy driveway that enters inside the work zone (Section 6H.03). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6H.03, 6H.06, 6H.07, 6H.15, 6H.18, 6H.20, 6H.22, 6H.24, 6H.28, 6H.36, 6H.37, 6G.10", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6k-spacing-1", "state": "US", "tier": "core", "title": "Cone spacing: in the taper and along the work", "topic": "Traffic control: cones, drums, barricades and arrow boards", "text": "MUTCD Section 6K.01 (Guidance): the spacing between cones, tubular markers, vertical panels, drums or barricades should not be more than 1 times the speed limit in feet in a taper, and not more than 2 times the speed limit in feet along a tangent (the straight run beside the buffer and the work space). At 25 mph that is 25 ft in the taper and 50 ft along the work; at 35 mph, 35 ft and 70 ft; at 45 mph, 45 ft and 90 ft; at 55 mph, 55 ft and 110 ft. Two tapers are different: the one-lane two-way taper in front of a flagger and the downstream taper use devices about 20 ft apart (Section 6B.08). How many cones for a taper: divide the taper length by the spacing and add one. A 245 ft taper at 35 mph takes 8 cones; a 540 ft taper at 45 mph takes 13. Warning lights on the devices, where used, follow the same spacing. Keep devices clean, upright and in line, and replace damaged ones (Standard). Tighter spacing is common at night, on curves and where drivers cut in. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6K.01 paras. 4-5, 14-15; Section 6B.08 paras. 12, 14", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6k-cones-1", "state": "US", "tier": "core", "title": "Cones, tubular markers and drums: minimum sizes", "topic": "Traffic control: cones, drums, barricades and arrow boards", "text": "Cones (Section 6K.03, Standard): mostly orange, made so a car can hit them without damage. At least 18 inches tall for daytime use on low-speed roads. At least 28 inches tall on freeways and other high-speed highways, at night on any road, and whenever more visible guidance is needed. For night use, a 28 to 36 inch cone has a 6 inch white reflective band 3 to 4 inches from the top and a 4 inch white band about 2 inches below it. Cones taller than 36 inches have alternating orange and white reflective stripes 4 to 6 inches wide, at least two of each, orange on top. Cones may be doubled up for weight. Tubular markers (Section 6K.04): at least 18 inches tall and 2 inches wide; 28 inches on freeways, high-speed roads and at night. Drums (Section 6K.06): at least 36 inches tall and 18 inches wide, lightweight and deformable, with orange and white reflective stripes 4 to 6 inches wide and a closed top; metal drums shall not be used and ballast shall not be put on top. All channelizing devices shall be crashworthy (Section 6K.01). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6K.01 para. 1, 6K.03 paras. 1-8, 6K.04 paras. 1-2, 6K.06 paras. 1-5", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6k-barricades-1", "state": "US", "tier": "core", "title": "Barricades: Type 1, 2 and 3 and when each is used", "topic": "Traffic control: cones, drums, barricades and arrow boards", "text": "A barricade has one, two or three rails with orange and white reflective stripes sloping down at 45 degrees toward the side traffic is to pass. Type 1 has one rail, Type 2 two, Type 3 three. Stripes are 6 inches wide; 4 inch stripes may be used on rails shorter than 36 inches. Minimum rail length is 24 inches for Type 1 and Type 2 and 48 inches for Type 3, and each rail is 8 to 12 inches wide (Section 6K.07, Standard). Type 1 may be used on conventional roads and city streets where traffic keeps moving through the zone. Type 2 and Type 3 suit freeways, expressways and high-speed roads. Type 3 is the device for closing a road or part of one; it may run curb to curb. Sandbags for ballast go low on the frame, never on top rails where they can come through a windshield. Vertical panels (8 to 12 inches wide, at least 24 inches of striping) may be used where space is tight (Section 6K.05). Water-filled longitudinal channelizing devices are not crashworthy barrier: do not use them to shield the crew (Section 6K.10). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6K.05 paras. 1-4, 6K.07 paras. 3-22, 6K.10 paras. 1-8", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6l-arrowboard-1", "state": "US", "tier": "core", "title": "Arrow boards: when the arrow is allowed and when it is caution only", "topic": "Traffic control: cones, drums, barricades and arrow boards", "text": "An arrow board in arrow or chevron mode is only for a stationary or moving lane closure on a multi-lane road (Section 6L.06, Standard). For shoulder work, for work beside the shoulder, for blocking the shoulder, and for closing one lane on a two-lane two-way road, the board shall be used only in caution mode (flashing caution or alternating diamond). An arrow board shows a lane closure, never a lane shift. Use one board for each closed lane. For a stationary closure it should sit on the shoulder at the start of the merging taper, or in the closed lane behind the cones if the shoulder is narrow. A vehicle carrying an arrow board shall also have high-intensity rotating, flashing, oscillating or strobe lights. Sizes (Figure 6L-3): Type A 48 by 24 inches for low-speed city streets; Type B 60 by 30 inches for intermediate speeds and for maintenance or mobile work on high-speed roads; Type C 96 by 48 inches for high-speed, high-volume roads. The board is dimmed at night, by at least half. An arrow board is required when a freeway lane is closed (TA-33). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6L.06 paras. 2-25; Figure 6L-3; Figure 6P-33 (TA-33) note 7", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6m-night-1", "state": "US", "tier": "core", "title": "Night work: lighting, flagger stations and visibility", "topic": "Traffic control: night work", "text": "Night work has less traffic, but drivers see less, drive faster and are more often tired or impaired (Section 6A.05). What the MUTCD calls for: flagger stations shall be illuminated at night except in an emergency (Sections 6D.06, 6M.08 and 6N.18, Standard). Floodlights should light the work area, equipment crossings and other areas, set so they do not glare into the eyes of drivers, flaggers or workers; check by driving through from each direction after setup and again during the night. A driver should be able to tell a worker is a person, and shadows that hide workers should be kept down. Light levels the manual gives: about 5 foot-candles for general work, 10 foot-candles around equipment, 20 foot-candles for close, careful tasks. All signs and channelizing devices used at night are retroreflective or lit; cones are at least 28 inches with the two white bands. Flaggers at night should wear Class 3 apparel. Add lights and reflective markings to work vehicles and equipment. Where night traffic is light enough, closing the road and detouring traffic takes the traffic risk out of the work area. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6A.05, 6M.08 paras. 1-6, 6N.18 paras. 2-7, 6K.03, 6C.05 para. 7", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6n-duration-1", "state": "US", "tier": "core", "title": "Work duration: the five categories that decide how much traffic control", "topic": "Traffic control: short jobs and mobile work", "text": "The MUTCD sorts work by how long it occupies one spot (Section 6N.01, Standard). Long-term stationary: more than 3 days. Intermediate-term stationary: more than one daylight period up to 3 days, or night work lasting more than 1 hour. Short-term stationary: daytime work that occupies a location more than 1 hour within a single daylight period. Short duration: up to 1 hour. Mobile: work that moves intermittently or continuously. The manual notes that most maintenance and utility work is short-term stationary. Long-term and intermediate-term zones run into the night, so their devices shall be retroreflective or illuminated. Long-term jobs are where temporary barrier, drums and changed pavement markings make sense. For short-duration and mobile work, setting up and taking down a full layout can take longer than the work and expose the crew more, so simplified control is allowed, built around a work truck with high-intensity flashing lights; but safety should not be cut just because the location changes often. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6N.01 paras. 1-11", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6n-short-1", "state": "US", "tier": "core", "title": "Short-duration (1 hour or less) and mobile work: what can be left out", "topic": "Traffic control: short jobs and mobile work", "text": "For work of 1 hour or less, and for mobile work, the MUTCD allows fewer devices if a vehicle with activated high-intensity rotating, flashing, oscillating or strobe lights is used. Work beyond the shoulder: for short-term, short-duration or mobile work all signs and cones may be left out (TA-1). Work on the shoulder: for 60 minutes or less the signs and cones may be left out (TA-3). Shoulder work with a small encroachment: for short-duration work the taper and cones may be left out if a shadow vehicle with lights is used (TA-6). In the center of an intersection: the cones may be left out for short-duration work if a vehicle with lights is in the work space (TA-26). Flaggers on a two-lane road: ROAD WORK AHEAD and END ROAD WORK may be left out for short-duration work, but the flagger signs stay (TA-10). Rules that do not bend (Standard): four-way hazard flashers may be added but shall not replace the high-intensity lights; an arrow board on a shoulder or two-lane road is in caution mode; signs on the truck are covered or turned when no work is going on. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6N.01 paras. 9-20; Figures 6P-1 note 4, 6P-3 note 5, 6P-6 note 10, 6P-10 note 3, 6P-26 note 6", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6n-shoulder-1", "state": "US", "tier": "core", "title": "Work off the road and on the shoulder: how much traffic control", "topic": "Traffic control: typical setups for utility work", "text": "Beyond the shoulder (Section 6N.05): work 15 ft or more from the edge of the traveled way generally needs no traffic control, unless trucks parked or entering, or equipment crossing, will distract drivers; then use a single ROAD WORK AHEAD sign, or SHOULDER WORK if vehicles are on the shoulder. The ROAD WORK AHEAD sign may be left out if the work is behind barrier, more than 24 inches behind the curb, or 15 ft or more from the road (TA-1). On the shoulder, road open (Section 6N.06): when a paved shoulder 8 ft or wider is closed, at least one advance warning sign shall be used, and channelizing devices shall close the shoulder ahead of the work, mark the start of the work space and keep traffic in the lanes (Standard). The shoulder taper is 1/3 L. An arrow board on the shoulder is in caution mode only. Shoulder work that takes part of a lane (Section 6N.07): unless the lane that is left is at least 10 ft wide, close the lane; 9 ft may be used for short-term work on low-volume, low-speed roads without wide trucks. This minor-encroachment setup is for low-speed minor roads; on faster roads close the lane (TA-6). The approved plan governs.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6N.05 paras. 1-4, 6N.06 paras. 2-9, 6N.07 paras. 2-4; Figures 6P-1 note 3, 6P-3 note 8, 6P-6 notes 1-4", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6n-utility-1", "state": "US", "tier": "core", "title": "Utility work in a street: the typical applications that fit", "topic": "Traffic control: typical setups for utility work", "text": "Section 6N.10 speaks to utility crews directly: utility work happens in and next to the road, often at intersections, with a small crew, few vehicles and few devices. To make up for fewer devices, use high-visibility ones, such as high-intensity flashing lights on the work trucks or a flag tree (Guidance). The manual names these typical applications as examples for utility work: TA-6 shoulder work with minor encroachment, TA-10 lane closure on a two-lane road using flaggers, TA-15 work in the center of a low-volume road, TA-18 lane closure on a minor street, TA-21 lane closure on the near side of an intersection, TA-22 and TA-23 lane closure on the far side of an intersection, TA-26 closure in the center of an intersection, and TA-33 stationary lane closure on a divided highway. Add TA-28 and TA-29 when a sidewalk or crosswalk is affected, and TA-1, TA-3 and TA-4 for work off the road or on the shoulder. A UTILITY WORK AHEAD sign (W21-7) may replace ROAD WORK AHEAD. In a street the plan also has to keep access to driveways and businesses, keep a bike route or sign another one, and keep access to any bus stop that is affected (Standard). The approved plan governs.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6N.10 paras. 2-10; Section 6H.24; Table 6P-1", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6n-intersection-1", "state": "US", "tier": "core", "title": "Work at an intersection: near side, far side and in the middle", "topic": "Traffic control: typical setups for utility work", "text": "The MUTCD sorts intersection work by where the work space sits (Section 6N.12). Near side (before the intersection): handled like a mid-block lane closure (TA-21). The merging taper shall move traffic into the right lane or the left lane, not both; a left-hand taper keeps right-turning cars from blocking through traffic. Far side (past the intersection, TA-22 to TA-25): drivers arrive straight through and from both turns, so if a lane is closed on the far side, also close it on the near-side approach so nobody merges inside the intersection. In the middle (TA-26 and TA-27): keep the work space small so traffic can pass around it, with lanes at least 10 ft wide, or use flaggers or police to direct traffic, or stage the work, or close an approach. Put advance warning signs on every street that enters. If the work space crosses a crosswalk, close the crosswalk the way TA-29 shows. Think about the signal: detectors, timing and signal heads over a closed lane may need changes, and if you expect capacity, operation or pedestrian access problems you shall contact the agency that owns the signal (Standard). The approved plan governs.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6N.12 paras. 2-16; Figures 6P-21 notes 1-3, 6P-22 note 1, 6P-26 note 1, 6P-27 notes 1-2", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6p-howto-1", "state": "US", "tier": "core", "title": "Typical applications (TA drawings): how to use them", "topic": "Traffic control: typical setups for utility work", "text": "Chapter 6P of the MUTCD has 54 typical applications, TA-1 to TA-54, each a drawing (Figure 6P-1 to 6P-54) with a page of notes. Table 6P-1 is the index and Table 6P-2 explains the symbols. On the drawings the sign spacing is shown as letters A, B and C from Table 6B-1, and taper lengths come from the formulas in Table 6B-4. Most drawings show devices for one direction only. The typical applications are minimum solutions and are generally treated as Guidance; a note on the notes page that is labeled Standard is a requirement. A real plan often combines two or three of them, for example a near-side lane closure on one street, a far-side closure on the cross street and a crosswalk closure. The plan may add devices, lengthen sign spacing or tapers to give drivers more time, and adjust for the site, and devices marked optional may be left out. Positive protection (barrier or a truck-mounted attenuator) may be added to almost any of them. Your state DOT's standard plans or work zone manual usually replace these drawings on state roads. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6P.01 paras. 1-7; Tables 6P-1 and 6P-2; Section 6B.01 paras. 21-25", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6p-ta10-1", "state": "US", "tier": "core", "title": "TA-10: lane closure on a two-lane road using flaggers", "topic": "Traffic control: typical setups for utility work", "text": "This is the standard setup when a trench takes one lane of a two-lane road. Advance signs in each direction: ROAD WORK AHEAD (or UTILITY WORK AHEAD), ONE LANE ROAD AHEAD, then the Flagger sign, spaced A, B and C from Table 6B-1. A BE PREPARED TO STOP sign may be added between the Flagger sign and the ONE LANE ROAD sign. A flagger at each end, a short one-lane two-way taper of 50 to 100 ft in front of the work with cones about 20 ft apart, a buffer space if there is room, cones along the work at no more than 2 times the speed limit in feet, and a downstream taper. Notes: one flagger may be used on a short, low-volume, straight job where that flagger can be seen from both directions. ROAD WORK AHEAD and END ROAD WORK may be left out for short-duration work. Flagger stations shall be lit at night except in emergencies (Standard). On a curve or hill crest, lengthen the buffer so the taper and the back of the queue are seen in time. An automated flagger device may be used where only one lane approaches. An arrow board here is caution mode only. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figure 6P-10 (TA-10) notes 1-13; Sections 6B.08, 6E.02, 6K.01, 6L.06 para. 18", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6p-shoulder-1", "state": "US", "tier": "core", "title": "TA-1, TA-3 and TA-4: work beyond the shoulder and on the shoulder", "topic": "Traffic control: typical setups for utility work", "text": "TA-1, work beyond the shoulder: one ROAD WORK AHEAD sign. The sign may be left out if the work space is behind a barrier, more than 24 inches behind the curb, or 15 ft or more from the edge of any roadway. For short-term, short-duration or mobile work, all signs and devices may be left out if a vehicle with activated high-intensity flashing lights is used. TA-3, work on the shoulder: SHOULDER WORK sign (a Workers sign may be used instead), a shoulder taper of 1/3 L and cones along the work. If a paved shoulder 8 ft or wider is closed, at least one advance warning sign and channelizing devices are required (Standard). For work of 60 minutes or less the signs and cones may be left out if a vehicle with activated lights is used. TA-4, short-duration or mobile work on a shoulder: stationary signs may be left out if the work vehicle shows high-intensity lights. In all three, four-way flashers do not replace the high-intensity lights, and an arrow board on the shoulder is caution mode only (Standard). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-1 (TA-1) notes 2-6, 6P-3 (TA-3) notes 3-8, 6P-4 (TA-4) notes 1-9", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-6p-ta28-1", "state": "US", "tier": "core", "title": "TA-28 and TA-29: sidewalk detour and crosswalk closure", "topic": "Traffic control: pedestrians and sidewalks", "text": "TA-28, sidewalk detour or diversion (Standard notes): the temporary route shall be detectable and have accessibility features consistent with the existing sidewalk. A pedestrian channelizing device that a long cane can detect shall span the full width of the closed sidewalk. Temporary ramps shall be 12:1 (8.33 percent) or flatter with a slip-resistant surface, with a landing at least 48 by 48 inches and 2 percent cross-slope or flatter. SIDEWALK CLOSED CROSS HERE signs shall include an audible information device. The route may be 48 inches wide with a 60 inch passing area every 200 ft. TA-29, crosswalk closure and pedestrian detour: the temporary crossing has the same detectable and accessible rules; curb parking shall be prohibited for at least 50 ft ahead of a temporary mid-block crosswalk (Standard); pedestrian signal heads for a closed crosswalk should be covered or turned off. Both drawings show only the pedestrian devices; the lane closure signs for vehicles come from the other typical applications. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-28 (TA-28) notes 1-14, 6P-29 (TA-29) notes 1-11", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-osha-subpartg-1", "state": "US", "tier": "core", "title": "OSHA and traffic control: 29 CFR 1926.200 and 1926.201", "topic": "Traffic control: OSHA rules", "text": "OSHA's construction rule on signs, signals and barricades is Subpart G. Two paragraphs make the MUTCD an OSHA requirement. 29 CFR 1926.200(g)(1): at points of hazard, construction areas shall be posted with legible traffic control signs and protected by traffic control devices. 1926.200(g)(2): the design and use of all traffic control devices, including signs, signals, markings, barricades and other devices, for the protection of construction workers shall conform to Part 6 of the MUTCD. 29 CFR 1926.201(a): signaling by flaggers and the use of flaggers, including their warning garments, shall conform to Part 6 of the MUTCD. So a missing taper, a flagger with no paddle or no vest, or a night flagger station with no light can be cited by OSHA as well as by the road agency. Subpart G today has only those two sections, 1926.200 and 1926.201; the old barricade section 1926.202 and definitions section 1926.203 are no longer in the rule (last amended at 84 FR 21577, May 14, 2019). Separately, 29 CFR 1926.651(d) requires high-visibility garments for excavation crews exposed to public traffic. States that run their own OSHA plan may have their own versions.", "source": "29 CFR 1926.200(g)(1)-(2); 29 CFR 1926.201(a); 29 CFR part 1926 subpart G (sections list); 29 CFR 1926.651(d)", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.200", "checked": "2026-11-20", "edition": "29 CFR part 1926 subpart G as amended at 84 FR 21577 (May 14, 2019)", "confidence": "high", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "mutcd-osha-edition-1", "state": "US", "tier": "core", "title": "Which MUTCD edition OSHA enforces", "topic": "Traffic control: OSHA rules", "text": "OSHA's construction rules name a specific edition of the MUTCD. 29 CFR 1926.6(n)(1) incorporates by reference the Manual on Uniform Traffic Control Devices for Streets and Highways, 2009 Edition, December 2009, including Revision 1 dated May 2012 and Revision 2 dated May 2012, for 1926.200(g) and 1926.201(a). The Federal Highway Administration and the states have moved on to the 11th Edition (December 2023, with Revision 1 dated December 2025). In practice a setup that meets the current state manual and the approved traffic control plan is what the road agency requires, and the main Part 6 numbers a crew uses did not change between the two editions: the taper formulas, the 100, 350 and 500 ft sign spacings, the stopping sight distance table used for buffers and flagger stations, the 28 inch night cone, and Class 2 or 3 apparel. What changed is mostly the numbering (flaggers moved from Chapter 6E to 6D, typical applications from Chapter 6H to 6P) and newer provisions. If a citation or a contract quotes a section number, check which edition it is quoting.", "source": "29 CFR 1926.6(n)(1); 29 CFR 1926.200(g)(2), 1926.201(a); MUTCD 11th Edition Part 6; OSHA highway work zones page (2009 Edition)", "url": "https://www.law.cornell.edu/cfr/text/29/1926.6", "checked": "2026-11-20", "edition": "29 CFR 1926.6 as read 2026-11-20; MUTCD 2009 Edition with Revisions 1 and 2 (May 2012)", "confidence": "medium", "kind": "summary", "license": "gov-us", "note": "The statement that the main numbers did not change between editions rests on the 11th Edition tables read today and the 2009-based values already in the Ask KB (ords 1982-1988), not on a side-by-side read of the 2009 PDF."}}]$kb$::jsonb) with ordinality t(e, i),
       (select max(ord) as mx from pb_ai.kb_chunks where version = 'b3e91f6c47d2') m
 where not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = t.e->'chunk'->>'id');

-- the version's row count (the Ask loader refuses a library whose rows don't match kb_versions.n)
update pb_ai.kb_versions v
   set n = c.n, counts = c.counts
  from (select sum(k)::int as n, jsonb_object_agg(lib, k) as counts
          from (select lib, count(*)::int as k from pb_ai.kb_chunks where version = 'b3e91f6c47d2' group by lib) x) c
 where v.version = 'b3e91f6c47d2';
-- drop the saved search index so workers rebuild it from the rows
delete from pb_ai.kb_index_parts where version = 'b3e91f6c47d2';
delete from pb_ai.kb_index where version = 'b3e91f6c47d2';
-- checks: ords must stay 0..n-1 with no gaps, ids unique
do $chk$
declare n int; mx int; d int;
begin
  select count(*), max(ord), count(distinct chunk->>'id') into n, mx, d from pb_ai.kb_chunks where version = 'b3e91f6c47d2';
  if mx <> n - 1 then raise exception 'FAIL ord gap: % rows, max ord %', n, mx; end if;
  if d <> n then raise exception 'FAIL duplicate chunk id: % ids for % rows', d, n; end if;
  if (select v.n from pb_ai.kb_versions v where v.version = 'b3e91f6c47d2') <> n then raise exception 'FAIL kb_versions.n'; end if;
end $chk$;
commit;
